('vocab_aerial_tourism','aerial tourism','noun','sightseeing trips and holidays in which visitors see places from the air','[{"senseId":"aerial_tourism_1","meaning":"sightseeing trips and holidays in which visitors see places from the air","acceptedParaphrases":["sightseeing from the air","holidays that show places from above"],"masteryContexts":[{"contextId":"u5_01_aerial_tourism_meaning","text":"Our hotel offers aerial tourism packages, including a short helicopter flight above the waterfalls.","meaning":"sightseeing trips that show places from the air","wrongMeanings":["holiday packages that include a stay at a luxury hotel","sightseeing trips that show places from the sea","holidays based on climbing and walking in the hills"]},{"contextId":"u5_01_aerial_tourism_paraphrase","text":"The small airport on the island was built mainly for aerial tourism, because most visitors come to take sightseeing flights over the coral reef.","meaning":"holidays and trips in which people see places from the air","wrongMeanings":["journeys made by business travellers who fly every week","tours that take visitors underground to see caves","holidays in which people travel by train across the island"]}],"situationDistractors":["A group of tourists boarded a coach and spent the afternoon visiting museums in the old town.","Passengers on the ferry stayed on deck and watched the harbour lights from the water.","The family drove along the coast road and stopped at a café for lunch.","The guide handed out leaflets and explained that the walking tour of the old harbour would last two hours.","A cruise ship docked at the port, and the passengers went ashore to buy postcards.","The hotel bar was full of guests who were watching a football match on the big screen."],"gapDistractors":[{"contextId":"u5_01_aerial_tourism_gap_1","answer":"aerial tourism","wrong":["coastal fishing","mountain walking","city shopping"]},{"contextId":"u5_01_aerial_tourism_gap_2","answer":"aerial tourism","wrong":["desert camping","river rafting","coach travel"]},{"contextId":"u5_01_aerial_tourism_gap_3","answer":"aerial tourism","wrong":["coach tourism","cruise tourism","beach tourism"]}],"spellingErrors":["arial tourism","aerial tourizm","aereal tourism","aerial turism","aerial tourisim","airial tourism"],"masteryPassages":[{"passageId":"u5_01_aerial_tourism_passage_1","contextId":"u5_01_aerial_tourism_gap_1","text":"Visitors to the glacier can take a short flight in a small helicopter. Many of them say that ____ is the best way to understand how huge the ice field really is.","answer":"aerial tourism"},{"passageId":"u5_01_aerial_tourism_passage_2","contextId":"u5_01_aerial_tourism_gap_2","text":"The island has few roads and many steep hills, so the tourist board has started to promote ____. For a small fee, visitors can fly over the beaches, forests and villages in a light aircraft.","answer":"aerial tourism"}],"contextDependentParaphrases":[],"wrongParaphrases":["sightseeing from a coach","holidays on a mountain railway","tours of underground caves"],"misleadingDistractors":["business travel between cities by aeroplane","training courses for people who want to become pilots","the transport of goods by aeroplane and helicopter"]}]'::jsonb,'[]'::jsonb,'["promote aerial tourism","aerial tourism industry","a form of aerial tourism"]'::jsonb,'live'),
('vocab_underwater_photography','underwater photography','noun','the activity of taking photographs beneath the surface of the sea, a lake or a river','[{"senseId":"underwater_photography_1","meaning":"the activity of taking photographs beneath the surface of the sea, a lake or a river","acceptedParaphrases":["taking pictures beneath the surface","camera work under the sea"],"masteryContexts":[{"contextId":"u5_02_underwater_photography_meaning","text":"Divers who take up underwater photography need a waterproof camera and a strong torch.","meaning":"the activity of taking photographs beneath the surface of the water","wrongMeanings":["the activity of painting scenes beneath the surface of the water","the activity of studying marine animals beneath the surface of the water","the activity of searching for treasure beneath the surface of the water"]},{"contextId":"u5_02_underwater_photography_paraphrase","text":"The festival displayed stunning underwater photography showing turtles, rays and brightly coloured fish.","meaning":"pictures taken beneath the surface of the water","wrongMeanings":["pictures drawn of animals that live in the sea","models of sea creatures made from shells and plastic","maps showing the routes taken by divers and ships"]}],"situationDistractors":["The diver collected rubbish from the seabed and put it into a net bag.","A sailor repaired the engine of the fishing boat before the storm arrived.","The guide pointed out a rare bird on top of the cliff, and the group raised their binoculars.","The chef at the hotel restaurant prepared fresh fish with lemon and herbs.","We queued at the check-in desk while the clerk weighed our suitcases.","The tour bus broke down on the mountain road, and everyone waited for a replacement."],"gapDistractors":[{"contextId":"u5_02_underwater_photography_gap_1","answer":"underwater photography","wrong":["desert photography","mountain climbing","wildlife painting"]},{"contextId":"u5_02_underwater_photography_gap_2","answer":"underwater photography","wrong":["mountain photography","studio portrait work","wedding photography"]},{"contextId":"u5_02_underwater_photography_gap_3","answer":"underwater photography","wrong":["wedding photography","portrait painting","sports reporting"]}],"spellingErrors":["underwatter photography","underwater fotography","underwater photograpy","underwater photgraphy","underwater photografy","underwatar photography"],"masteryPassages":[{"passageId":"u5_02_underwater_photography_passage_1","contextId":"u5_02_underwater_photography_gap_1","text":"The young diver always carried a waterproof camera in a special case. She loved ____ because it let her share the colours of the reef with people who would never see them.","answer":"underwater photography"},{"passageId":"u5_02_underwater_photography_passage_2","contextId":"u5_02_underwater_photography_gap_2","text":"The magazine wanted pictures of sharks, turtles and coral for its summer issue, so it asked a diver with a professional camera to take them. His skill in ____ meant that even the deepest dives produced sharp, colourful images.","answer":"underwater photography"}],"contextDependentParaphrases":[],"wrongParaphrases":["taking pictures from a helicopter","painting scenes of the seaside","collecting shells from the beach"],"misleadingDistractors":["painting pictures of ships and sea creatures","the study of fish and other sea animals","selling cameras and diving equipment in shops"]}]'::jsonb,'[]'::jsonb,'["underwater photography course","professional underwater photography","specialise in underwater photography"]'::jsonb,'live'),
('vocab_documentary','documentary','noun','a film or television programme that presents real facts about a subject or an event','[{"senseId":"documentary_1","meaning":"a film or television programme that presents real facts about a subject or an event","acceptedParaphrases":["factual film","non-fiction programme"],"masteryContexts":[{"contextId":"u5_03_documentary_meaning","text":"After watching a documentary about Iceland, Hana decided to spend her summer holiday there.","meaning":"a factual film about real places or events","wrongMeanings":["an invented story with famous actors","a live broadcast of a sports event","a music show with singers and dancers"]},{"contextId":"u5_03_documentary_paraphrase","text":"The documentary follows a team of explorers as they cross the desert on camels.","meaning":"a programme that shows real events and people","wrongMeanings":["a comedy that makes viewers laugh","a game show with questions and prizes","a news report read by a presenter"]}],"situationDistractors":["The children laughed at a cartoon about a clumsy penguin who kept falling off an iceberg.","The actors rehearsed their lines for the school play on a stage built from wooden boxes.","The radio presenter read out the weather forecast and the traffic news for the morning.","The tourists bought tickets for the evening show and sat in the front row of the theatre.","At the airport café, a waiter brought two coffees and a plate of biscuits.","The hotel manager apologised because the lift was broken and the guests had to use the stairs."],"gapDistractors":[{"contextId":"u5_03_documentary_gap_1","answer":"documentary","wrong":["comedy","musical","thriller"]},{"contextId":"u5_03_documentary_gap_2","answer":"documentary","wrong":["comedy","thriller","cartoon"]},{"contextId":"u5_03_documentary_gap_3","answer":"documentary","wrong":["advert","quiz show","soap opera"]}],"spellingErrors":["documentry","documantary","documentery","docementary","documentarry","dokumentary"],"masteryPassages":[{"passageId":"u5_03_documentary_passage_1","contextId":"u5_03_documentary_gap_1","text":"On the flight home, Marcus watched a ____ about the people who live on the shores of Lake Baikal. He enjoyed it so much that he decided to read more about the region.","answer":"documentary"},{"passageId":"u5_03_documentary_passage_2","contextId":"u5_03_documentary_gap_2","text":"The local television station is planning a new ____ for the summer. The film crew will interview fishermen, hotel owners and guides to show what tourism has really done to the coast.","answer":"documentary"}],"contextDependentParaphrases":[],"wrongParaphrases":["cartoon series","adventure story","weather forecast"],"misleadingDistractors":["a story about imaginary people and events","a short advertisement shown between programmes","a live broadcast of a sports match"]}]'::jsonb,'[]'::jsonb,'["nature documentary","watch a documentary","make a documentary"]'::jsonb,'live'),
('vocab_snorkelling','snorkelling','noun','swimming near the surface of the water with a mask and a breathing tube to look at underwater life','[{"senseId":"snorkelling_1","meaning":"swimming near the surface of the water with a mask and a breathing tube to look at underwater life","acceptedParaphrases":["swimming with a mask and tube","shallow-water swimming with breathing gear"],"masteryContexts":[{"contextId":"u5_04_snorkelling_meaning","text":"The hotel lends masks and tubes to guests who want to go snorkelling in the bay.","meaning":"swimming near the surface with a mask and breathing tube","wrongMeanings":["sailing across the bay in a small boat","swimming to the bottom with heavy air tanks","fishing from the beach with a line and hook"]},{"contextId":"u5_04_snorkelling_paraphrase","text":"Families love snorkelling because it needs little training, and it lets children see fish up close.","meaning":"swimming on the surface to look at underwater life","wrongMeanings":["riding on the waves to practise balance","sailing on the sea to watch the sunset","walking along the shore to find shells"]}],"situationDistractors":["The lifeguard blew her whistle and told the swimmers to leave the pool because of the storm.","A group of cyclists stopped at the harbour to buy bottles of water and fruit.","The captain steered the ferry slowly past the lighthouse while passengers took photographs.","The tour guide counted the group twice before the coach left the car park.","A family unpacked a picnic of bread, cheese and fruit on the grass beside the lake.","The hotel pool was closed in the morning because workers were cleaning the tiles."],"gapDistractors":[{"contextId":"u5_04_snorkelling_gap_1","answer":"snorkelling","wrong":["sailing","windsurfing","fishing"]},{"contextId":"u5_04_snorkelling_gap_2","answer":"snorkelling","wrong":["sunbathing","shopping","hiking"]},{"contextId":"u5_04_snorkelling_gap_3","answer":"snorkelling","wrong":["fishing","sailing","camping"]}],"spellingErrors":["snorkeling","snorkling","snorckelling","snorkelng","snorkellign","snoorkelling"],"wordFamilyForms":[{"form":"snorkelling","partOfSpeech":"noun","example":"The hotel runs snorkelling trips to the reef every morning.","pedagogicallyUseful":true},{"form":"snorkel","partOfSpeech":"verb","example":"Visitors can snorkel above the wreck at low tide.","pedagogicallyUseful":true,"altExample":"You can snorkel for hours without getting tired in such calm water."},{"form":"snorkeller","partOfSpeech":"noun","example":"A young snorkeller spotted a turtle near the rocks.","pedagogicallyUseful":true,"altExample":"Each snorkeller received a mask, a tube and a pair of fins."}],"masteryPassages":[{"passageId":"u5_04_snorkelling_passage_1","contextId":"u5_04_snorkelling_gap_1","text":"We rented fins, masks and breathing tubes from the beach hut. For the next hour we went ____ along the edge of the reef and watched turtles, rays and shoals of tiny silver fish.","answer":"snorkelling"},{"passageId":"u5_04_snorkelling_passage_2","contextId":"u5_04_snorkelling_gap_2","text":"Scuba divers need years of training and heavy air tanks, but my little brother has no such equipment. For him, ____ is perfect: he floats on the surface in shallow water and simply looks down at the colourful world below.","answer":"snorkelling"}],"contextDependentParaphrases":[],"wrongParaphrases":["sailing in a small boat","diving with heavy air tanks","surfing on large waves"],"misleadingDistractors":["riding on waves while standing on a board","travelling across the sea on a large ship","catching fish with a net from a small boat"]}]'::jsonb,'["snorkel","snorkeller"]'::jsonb,'["go snorkelling","snorkelling trip","snorkelling equipment"]'::jsonb,'live'),
('vocab_expedition','expedition','noun','an organised journey made by a group of people to explore a place or to do research','[{"senseId":"expedition_1","meaning":"an organised journey made by a group of people to explore a place or to do research","acceptedParaphrases":["research journey","organised exploring trip"],"masteryContexts":[{"contextId":"u5_05_expedition_meaning","text":"Months of planning went into the expedition to climb the mountain, and dozens of porters carried the supplies.","meaning":"an organised journey made to explore or to reach a goal","wrongMeanings":["a short walk taken for exercise and fresh air","a holiday booked through a travel company","a competition held between two mountain clubs"]},{"contextId":"u5_05_expedition_paraphrase","text":"The university sent an expedition to the rainforest to record rare birds and plants.","meaning":"an organised group journey for research or exploration","wrongMeanings":["a lesson taught outdoors in a school garden","a meeting of scientists in a university building","an exhibition of animals kept in a zoo"]}],"situationDistractors":["The family flew to a beach resort and spent a lazy week by the pool.","Passengers waited at the gate while the airline checked their boarding passes.","We took the tram to the city centre and queued to buy tickets for the museum.","The waiter at the beach café brought ice cream to the children at the next table.","A guide pointed out the clock tower and told visitors about its history.","The shopkeeper rolled up the shutters and put boxes of fruit outside the door."],"gapDistractors":[{"contextId":"u5_05_expedition_gap_1","answer":"expedition","wrong":["commute","lesson","meeting"]},{"contextId":"u5_05_expedition_gap_2","answer":"expedition","wrong":["wedding","exam","festival"]},{"contextId":"u5_05_expedition_gap_3","answer":"expedition","wrong":["holiday","election","concert"]}],"spellingErrors":["expidition","expedishion","expeditoin","expedtion","expeditian","expediton"],"masteryPassages":[{"passageId":"u5_05_expedition_passage_1","contextId":"u5_05_expedition_gap_1","text":"The team spent a year raising money, buying equipment and training in the snow. At last they left on the ____ to reach the South Pole on foot.","answer":"expedition"},{"passageId":"u5_05_expedition_passage_2","contextId":"u5_05_expedition_gap_2","text":"Scientists from three countries travelled deep into the rainforest to search for new species of frogs. The ____ lasted eight weeks, and every member of the team kept a daily record of what they found.","answer":"expedition"}],"contextDependentParaphrases":[],"wrongParaphrases":["daily commute","shopping trip","family holiday"],"misleadingDistractors":["a short walk taken for exercise","a holiday spent resting at a hotel","a meeting held to make decisions"]}]'::jsonb,'[]'::jsonb,'["lead an expedition","research expedition","join an expedition"]'::jsonb,'live'),
('vocab_yacht','yacht','noun','a large boat with sails or an engine, used for pleasure or for racing','[{"senseId":"yacht_1","meaning":"a large boat with sails or an engine, used for pleasure or for racing","acceptedParaphrases":["pleasure boat","private sailing boat"],"masteryContexts":[{"contextId":"u5_06_yacht_meaning","text":"The millionaire invited his guests aboard his yacht for a weekend cruise along the Mediterranean coast.","meaning":"a large boat used for pleasure or sport","wrongMeanings":["a small boat used for catching fish","a large ship used for carrying goods","a long boat used for rescuing people"]},{"contextId":"u5_06_yacht_paraphrase","text":"On the day of the race, every yacht in the harbour raised its sails and moved slowly towards the starting line.","meaning":"a boat with sails used for pleasure or racing","wrongMeanings":["a ship used by the navy for defence","a boat used by workers to cross a river","a vessel used for carrying cars and lorries"]}],"situationDistractors":["The commuter ferry crossed the river every ten minutes, carrying workers to the city.","Fishermen pulled in their nets at dawn and sold the catch at the harbour market.","The huge container ship was unloaded by cranes at the port for two days.","The tourists spent the afternoon on the beach, building sandcastles and eating ice cream.","A cyclist stopped at the viewpoint to rest and drink some water.","The coach parked outside the museum, and the guide collected the tickets."],"gapDistractors":[{"contextId":"u5_06_yacht_gap_1","answer":"yacht","wrong":["ferry","tanker","lorry"]},{"contextId":"u5_06_yacht_gap_2","answer":"yacht","wrong":["bicycle","tractor","caravan"]},{"contextId":"u5_06_yacht_gap_3","answer":"yacht","wrong":["minibus","helicopter","taxi"]}],"spellingErrors":["yaht","yatch","yaught","yackt","yacth","yahct"],"masteryPassages":[{"passageId":"u5_06_yacht_passage_1","contextId":"u5_06_yacht_gap_1","text":"The harbour was full of expensive white boats with tall masts. The owner invited us aboard his ____, a sleek vessel built for racing and for luxury holidays at sea.","answer":"yacht"},{"passageId":"u5_06_yacht_passage_2","contextId":"u5_06_yacht_gap_2","text":"My uncle loves sailing, and he saved money for ten years. Last summer he finally bought a second-hand ____ and spent every weekend sailing along the coast.","answer":"yacht"}],"contextDependentParaphrases":[],"wrongParaphrases":["fishing boat","cargo ship","passenger ferry"],"misleadingDistractors":["a large ship that carries goods across oceans","a small boat used only for catching fish","a public ferry that crosses a river each day"]}]'::jsonb,'[]'::jsonb,'["luxury yacht","private yacht","yacht club"]'::jsonb,'live'),
('vocab_scenery','scenery','noun','the natural views of an area, such as hills, forests, rivers and lakes','[{"senseId":"scenery_1","meaning":"the natural views of an area, such as hills, forests, rivers and lakes","acceptedParaphrases":["natural views","beautiful countryside"],"masteryContexts":[{"contextId":"u5_07_scenery_meaning","text":"We stopped the coach several times so that the passengers could photograph the stunning scenery of mountains, rivers and forests.","meaning":"the natural views of an area","wrongMeanings":["the old buildings of a large city","the people who live in a village","the animals kept on a farm"]},{"contextId":"u5_07_scenery_paraphrase","text":"The mountain scenery is the main reason why so many hikers return to the region every year.","meaning":"the natural beauty of the land, such as hills, lakes and forests","wrongMeanings":["the quality of the hotels and restaurants","the cost of the equipment and guides","the safety of the paths and bridges"]}],"situationDistractors":["The hotel receptionist gave each guest a key card and a map of the building.","Shoppers hurried through the market, comparing prices before buying souvenirs.","The coach driver checked the tyres and filled the tank with diesel before the long trip.","The airline lost one of the family’s suitcases and promised to send it to the hotel.","The hotel guests queued at the buffet, where the chef was serving pasta and salad.","A taxi driver waited outside the station and held up a sign with a name on it."],"gapDistractors":[{"contextId":"u5_07_scenery_gap_1","answer":"scenery","wrong":["luggage","timetables","traffic"]},{"contextId":"u5_07_scenery_gap_2","answer":"scenery","wrong":["nightlife","shopping","food"]},{"contextId":"u5_07_scenery_gap_3","answer":"scenery","wrong":["economy","population","transport"]}],"spellingErrors":["senery","sceneery","scenary","scennery","sceenery","scenerie"],"masteryPassages":[{"passageId":"u5_07_scenery_passage_1","contextId":"u5_07_scenery_gap_1","text":"The bus climbs slowly along the edge of the cliff, and nobody minds the delay. The ____ outside, with its green hills and silver waterfalls, is the main reason people book this tour.","answer":"scenery"},{"passageId":"u5_07_scenery_passage_2","contextId":"u5_07_scenery_gap_2","text":"Our guide promised that the hike would be difficult, but she also said that the ____ would make every step worthwhile. At the summit, we could see forests, rivers and distant mountains in every direction.","answer":"scenery"}],"contextDependentParaphrases":[],"wrongParaphrases":["local customs","weather conditions","tourist facilities"],"misleadingDistractors":["the old buildings and monuments in a city","the weather and temperature of a region","the plants and animals kept in a zoo"]}]'::jsonb,'[]'::jsonb,'["spectacular scenery","enjoy the scenery","mountain scenery"]'::jsonb,'live'),
('vocab_attractions','attractions','noun','interesting or enjoyable places that tourists visit, such as museums, castles and theme parks','[{"senseId":"attractions_1","meaning":"interesting or enjoyable places that tourists visit, such as museums, castles and theme parks","acceptedParaphrases":["places of interest","sights for visitors"],"masteryContexts":[{"contextId":"u5_08_attractions_meaning","text":"Tourist attractions such as the old fort and the harbour museum are within walking distance of the hotel.","meaning":"interesting places that visitors go to see","wrongMeanings":["places where visitors can stay overnight","places where visitors can buy food and gifts","places where visitors can catch buses and trains"]},{"contextId":"u5_08_attractions_paraphrase","text":"Theme parks and zoos are popular attractions for families with young children.","meaning":"places that people visit because they are interesting or enjoyable","wrongMeanings":["places that people leave because they are noisy or expensive","places that people work in because they are busy or well paid","places that people study in because they are quiet or large"]}],"situationDistractors":["The receptionist gave us a room on the fourth floor with a view of the car park.","The airline lost one of our suitcases, and the staff promised to deliver it the next day.","The taxi driver took a wrong turning, and we arrived at the airport ten minutes late.","The hotel gym opens at six in the morning and closes at ten at night.","A waiter handed round the bill, and the group shared the cost between them.","Rain began to fall on the beach, and the sunbathers ran to find shelter."],"gapDistractors":[{"contextId":"u5_08_attractions_gap_1","answer":"attractions","wrong":["factories","offices","warehouses"]},{"contextId":"u5_08_attractions_gap_2","answer":"attractions","wrong":["islands","airlines","seasons"]},{"contextId":"u5_08_attractions_gap_3","answer":"attractions","wrong":["meals","airlines","lessons"]}],"spellingErrors":["atractions","attracsions","attractons","atracttions","attractoins","attrations"],"wordFamilyForms":[{"form":"attractions","partOfSpeech":"noun","example":"The city has many cultural attractions, including a museum and an opera house.","pedagogicallyUseful":true},{"form":"attract","partOfSpeech":"verb","example":"Warm weather and clean beaches attract millions of visitors to the coast every summer.","pedagogicallyUseful":true,"altExample":"New museums are helping to attract more young visitors to the town."},{"form":"attractive","partOfSpeech":"adjective","example":"The harbour is an attractive place for a walk in the evening.","pedagogicallyUseful":true,"altExample":"Thanks to its attractive beaches and old streets, the town is popular in summer."}],"masteryPassages":[{"passageId":"u5_08_attractions_passage_1","contextId":"u5_08_attractions_gap_1","text":"The old town is small, but it is packed with things to see. Within a ten-minute walk of the main square, visitors can reach the cathedral, the castle and the art museum, which are the region’s best-known tourist ____.","answer":"attractions"},{"passageId":"u5_08_attractions_passage_2","contextId":"u5_08_attractions_gap_2","text":"We had only one day in the capital, so we asked the hotel receptionist which ____ were worth visiting. She suggested the royal palace, the river cruise and the science museum.","answer":"attractions"}],"contextDependentParaphrases":[],"wrongParaphrases":["holiday apartments","shopping centres","travel agencies"],"misleadingDistractors":["hotels and apartments where visitors stay","shops and markets where visitors buy gifts","buses and trains that visitors use to travel"]}]'::jsonb,'["attract","attractive"]'::jsonb,'["tourist attractions","major attractions","attractions for families"]'::jsonb,'live'),
('vocab_accommodation','accommodation','noun','a place to stay, such as a hotel room or a flat, while you are away from home','[{"senseId":"accommodation_1","meaning":"a place to stay, such as a hotel room or a flat, while you are away from home","acceptedParaphrases":["a place to stay","somewhere to stay overnight"],"masteryContexts":[{"contextId":"u5_09_accommodation_meaning","text":"The student hostel offers cheap accommodation near the station, with shared kitchens and four-bed rooms.","meaning":"a place to stay when you are away from home","wrongMeanings":["a meal prepared and served to guests","a vehicle that takes guests to the station","a ticket that allows guests to travel"]},{"contextId":"u5_09_accommodation_paraphrase","text":"Finding suitable accommodation can be difficult in a seaside town during the summer season.","meaning":"rooms or buildings where you can stay for a period of time","wrongMeanings":["restaurants or cafés where you can eat during a visit","shops or stalls where you can buy souvenirs during a visit","tours or trips on which you can see sights during a visit"]}],"situationDistractors":["The waiter brought a menu to our table and recommended the fish of the day.","Passengers queued at the security gate and placed their bags on the belt.","The guide held up a flag so that the group could find her in the crowded square.","The tour company printed a new leaflet showing the museum’s opening hours.","The family watched the sunset from the harbour wall and took photographs.","A guide stood at the front of the coach and described the villages along the road."],"gapDistractors":[{"contextId":"u5_09_accommodation_gap_1","answer":"accommodation","wrong":["transport","entertainment","insurance"]},{"contextId":"u5_09_accommodation_gap_2","answer":"accommodation","wrong":["flights","tickets","taxis"]},{"contextId":"u5_09_accommodation_gap_3","answer":"accommodation","wrong":["transport","insurance","equipment"]}],"spellingErrors":["acommodation","accomodation","accommodaton","acomodation","accommadation","accommodtion"],"masteryPassages":[{"passageId":"u5_09_accommodation_passage_1","contextId":"u5_09_accommodation_gap_1","text":"Our flight arrived after midnight, and the airport was almost empty. Fortunately, the travel agent had arranged our ____ in advance, together with breakfast and an airport pick-up.","answer":"accommodation"},{"passageId":"u5_09_accommodation_passage_2","contextId":"u5_09_accommodation_gap_2","text":"Prices in the city centre are high, so students on a small budget often look for cheap ____ on the edge of town. A bed in a shared hostel costs less than a quarter of the price of a hotel room.","answer":"accommodation"}],"contextDependentParaphrases":[],"wrongParaphrases":["a way to travel","a place to eat","a type of ticket"],"misleadingDistractors":["the food served in a hotel restaurant","the staff who work at a hotel reception","the transport provided between the airport and the hotel"]}]'::jsonb,'[]'::jsonb,'["book accommodation","cheap accommodation","student accommodation"]'::jsonb,'live'),
('vocab_adventurous','adventurous','adjective','willing to try new, exciting or sometimes dangerous things','[{"senseId":"adventurous_1","meaning":"willing to try new, exciting or sometimes dangerous things","acceptedParaphrases":["daring","keen to try new things"],"masteryContexts":[{"contextId":"u5_10_adventurous_meaning","text":"My brother is very adventurous, so he booked a kayaking trip through the rapids instead of a relaxing beach holiday.","meaning":"willing to try new and exciting things, even if they are risky","wrongMeanings":["unwilling to leave home or try new foods","interested in history and old buildings","careful to plan every detail of a trip"]},{"contextId":"u5_10_adventurous_paraphrase","text":"The company organises holidays for adventurous teenagers who would rather hike across glaciers than sit by a pool.","meaning":"keen on exciting new experiences","wrongMeanings":["worried about danger and discomfort","proud of their wealth and success","good at making friends quickly"]}],"situationDistractors":["The tourist checked the weather forecast three times and then stayed in the hotel all day.","The couple booked the same hotel they had visited for ten years and ate at the same café every evening.","The woman packed a guidebook, a map and a first-aid kit, and she followed the planned route exactly.","The guide gave clear safety instructions, and the group listened carefully before they began the gentle walk.","The elderly couple spent a quiet week at the same seaside hotel, reading books and doing crosswords.","The teenager checked every item on his packing list twice and took only the things he really needed."],"gapDistractors":[{"contextId":"u5_10_adventurous_gap_1","answer":"adventurous","wrong":["cautious","lazy","nervous"]},{"contextId":"u5_10_adventurous_gap_2","answer":"adventurous","wrong":["sleepy","cautious","homesick"]},{"contextId":"u5_10_adventurous_gap_3","answer":"adventurous","wrong":["careful","patient","tired"]}],"spellingErrors":["adventerous","advanturous","adventurus","adventourous","adveturous","adventrous"],"wordFamilyForms":[{"form":"adventurous","partOfSpeech":"adjective","example":"Lena is adventurous and always chooses the most exciting activity on the programme.","pedagogicallyUseful":true},{"form":"adventure","partOfSpeech":"noun","example":"Their journey across Africa was the greatest adventure of their lives.","pedagogicallyUseful":true,"altExample":"The school trip turned into a real adventure when the bus broke down in the mountains."},{"form":"adventurer","partOfSpeech":"noun","example":"The famous adventurer crossed three oceans in a small wooden boat.","pedagogicallyUseful":true,"altExample":"Every adventurer in the camp carried a compass, a torch and a first-aid kit."}],"masteryPassages":[{"passageId":"u5_10_adventurous_passage_1","contextId":"u5_10_adventurous_gap_1","text":"Most people in the tour group wanted to relax by the hotel pool. Anya, however, was far more ____: she hired a bicycle, cycled up the mountain road and jumped into a waterfall.","answer":"adventurous"},{"passageId":"u5_10_adventurous_passage_2","contextId":"u5_10_adventurous_gap_2","text":"The tour company’s advertisement says that its holidays are designed for ____ people who enjoy new challenges. Guests can try rock climbing, canoeing and camping in remote places.","answer":"adventurous"}],"contextDependentParaphrases":[],"wrongParaphrases":["cautious","generous","sociable"],"misleadingDistractors":["unwilling to take any risks at all","very interested in history and old buildings","always ready to help other people"]}]'::jsonb,'["adventure","adventurer"]'::jsonb,'["adventurous spirit","adventurous traveller","feel adventurous"]'::jsonb,'live')
