('u5_01_aerial_tourism_meaning','vocab_aerial_tourism','u5_01_aerial_tourism','aerial_tourism_1','meaning_context','Helicopter flights over the glaciers have helped to make aerial tourism a growing business in the region.',null,'["sightseeing from the air"]'::jsonb,null,'live'),
('u5_01_aerial_tourism_paraphrase','vocab_aerial_tourism','u5_01_aerial_tourism','aerial_tourism_1','paraphrase_context','Helicopter flights over the glaciers have helped to make sightseeing from the air a growing business in the region.','sightseeing from the air','["aerial tourism"]'::jsonb,null,'live'),
('u5_01_aerial_tourism_production','vocab_aerial_tourism','u5_01_aerial_tourism','aerial_tourism_1','production_context','The island now earns most of its money from holidays that show places from above, such as helicopter and balloon trips.','holidays that show places from above','["aerial tourism"]'::jsonb,null,'live'),
('u5_01_aerial_tourism_gap_1','vocab_aerial_tourism','u5_01_aerial_tourism','aerial_tourism_1','gap_fill','Helicopter rides over the volcano are the most popular form of aerial tourism on the island.','aerial tourism','["aerial tourism"]'::jsonb,null,'live'),
('u5_01_aerial_tourism_gap_2','vocab_aerial_tourism','u5_01_aerial_tourism','aerial_tourism_1','gap_fill','Visitors who prefer aerial tourism can see the whole canyon in twenty minutes from a small plane.','aerial tourism','["aerial tourism"]'::jsonb,null,'live'),
('u5_01_aerial_tourism_gap_3','vocab_aerial_tourism','u5_01_aerial_tourism','aerial_tourism_1','gap_fill','Strict rules limit how low helicopters may fly, so aerial tourism does not disturb the people living near the national park.','aerial tourism','["aerial tourism"]'::jsonb,null,'live'),
('u5_02_underwater_photography_meaning','vocab_underwater_photography','u5_02_underwater_photography','underwater_photography_1','meaning_context','The magazine hired an expert in underwater photography to capture the colours of the coral reef.',null,'["taking pictures beneath the surface"]'::jsonb,null,'live'),
('u5_02_underwater_photography_paraphrase','vocab_underwater_photography','u5_02_underwater_photography','underwater_photography_1','paraphrase_context','The magazine hired an expert in taking pictures beneath the surface to capture the colours of the coral reef.','taking pictures beneath the surface','["underwater photography"]'::jsonb,null,'live'),
('u5_02_underwater_photography_production','vocab_underwater_photography','u5_02_underwater_photography','underwater_photography_1','production_context','Good results in camera work under the sea depend on clear water and bright light.','camera work under the sea','["underwater photography"]'::jsonb,null,'live'),
('u5_02_underwater_photography_gap_1','vocab_underwater_photography','u5_02_underwater_photography','underwater_photography_1','gap_fill','Her interest in underwater photography began when she took a waterproof camera on a diving holiday.','underwater photography','["underwater photography"]'::jsonb,null,'live'),
('u5_02_underwater_photography_gap_2','vocab_underwater_photography','u5_02_underwater_photography','underwater_photography_1','gap_fill','Clear, shallow water and bright sunshine are ideal conditions for underwater photography on the reef.','underwater photography','["underwater photography"]'::jsonb,null,'live'),
('u5_02_underwater_photography_gap_3','vocab_underwater_photography','u5_02_underwater_photography','underwater_photography_1','gap_fill','The museum’s exhibition of underwater photography shows shipwrecks, sharks and forests of seaweed.','underwater photography','["underwater photography"]'::jsonb,null,'live'),
('u5_03_documentary_meaning','vocab_documentary','u5_03_documentary','documentary_1','meaning_context','The tourist board paid for a documentary about the wildlife of the Amazon rainforest.',null,'["factual film"]'::jsonb,null,'live'),
